/* One native archive for both classic and show difficulties; shared resource bytes are fetched once. */
'use strict';
(function(root){
async function make(info,getResource,progress=()=>{}){const A=root.DCAccountCore,C=root.DCCore,support=A.packageSupport(info),count=support.classic.length+support.show.length;if(!count)throw Error(support.reason);const responses=new Map(),read=(url,context)=>{if(!responses.has(url))responses.set(url,Promise.resolve().then(()=>getResource(url,context)).then(value=>value?.data??(value instanceof Response?A.readBytes(value,context.max):value)).then(value=>value instanceof Uint8Array?value:new Uint8Array(value)));return responses.get(url).then(bytes=>{if(bytes.length>context.max)throw Error('资源超过单文件限制');return{data:bytes};});};let done=0;const files=[],warnings=[],charts=[];let song;
if(support.classic.length){const result=await A.makePackage(info,read,p=>progress((done+p*support.classic.length)/count));files.push(...result.files);warnings.push(...result.warnings);charts.push(...result.charts);song=result.song;done+=support.classic.length;}
if(support.show.length){const result=await root.DCShow.makePackage(info,read,p=>progress((done+p*support.show.length)/count));const replacements=new Map(),fingerprints=new Map(files.filter(f=>!/\.(?:mc|json)$/i.test(f.name)).map(f=>[f.data.length+':'+C.crc32(f.data),f]));for(const file of result.files){if(file.name==='dc-show.json')continue;const same=fingerprints.get(file.data.length+':'+C.crc32(file.data));if(same&&(same.data===file.data||same.data.every((v,i)=>v===file.data[i])))replacements.set(file.name,same.name);else files.push(file);}for(const chart of result.manifest.charts)for(const key of ['audioName','backgroundName','titleImage','txtFile','svFile'])if(replacements.has(chart[key]))chart[key]=replacements.get(chart[key]);files.push({name:'dc-show.json',data:new TextEncoder().encode(JSON.stringify(result.manifest,null,2))});warnings.push(...result.warnings);song=result.manifest.song;charts.push(...result.manifest.charts);}
const unique=new Map();let size=0;for(const f of files){if(unique.has(f.name))throw Error('混合谱包存在重名资源：'+f.name);size+=f.data.length;if(size>150*1024*1024)throw Error('混合谱包超过 150 MB');unique.set(f.name,f);}progress(1);return{song,charts,files:[...unique.values()],warnings:[...new Set(warnings)],blob:C.zipStore([...unique.values()])};}
root.DCOnlinePackage={make};
})(typeof window==='undefined'?globalThis:window);
